kit.scene('brothers', {
  init(kit) {
    this.s = W.shot(kit, {
      id: 'brothers', bg: 'court', glow: true,
      cast: [{ who: 'ravana', x: 500, y: 1330, s: 1.15 }],
      cam: [1.0, 1.07, 459, 560, 470, 600],
      arm: (t, i, talk) => -10 + 6 * Math.sin(t * 1.4),
      lines: [[41.8, 44.3, 'फिर किसलिए लड़े मेरे भाई…', 0, 0], [44.6, 45.55, 'किसलिए?', 0, 0]],
    });
  },
  render(t) { this.s.render(t); },
});
